import{_ as e,c as r,o as i,ah as n}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"16、【豫】 坤下震上","description":"溫公易說 - 16、【豫】 坤下震上","frontmatter":{"title":"16、【豫】 坤下震上","description":"溫公易說 - 16、【豫】 坤下震上"},"headers":[],"relativePath":"classics/wengong/017.md","filePath":"classics/wengong/017.md"}'),l={name:"classics/wengong/017.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_16、【豫】-坤下震上" tabindex="-1">16、【豫】 坤下震上 <a class="header-anchor" href="#_16、【豫】-坤下震上" aria-label="Permalink to “16、【豫】 坤下震上”">​</a></h1><h3 id="彖曰-豫-剛應而志行-順以動-豫。豫順以動-故天地如之-而況建侯行師乎-天地以順動-故日月不過-而四時不忒。聖人以順動-則刑罰清而民服。豫之時義-大矣哉" tabindex="-1">彖曰：豫，剛應而志行，順以動，豫。豫順以動，故天地如之，而況建侯行師乎？天地以順動，故日月不過，而四時不忒。聖人以順動，則刑罰清而民服。豫之時義，大矣哉！ <a class="header-anchor" href="#彖曰-豫-剛應而志行-順以動-豫。豫順以動-故天地如之-而況建侯行師乎-天地以順動-故日月不過-而四時不忒。聖人以順動-則刑罰清而民服。豫之時義-大矣哉" aria-label="Permalink to “彖曰：豫，剛應而志行，順以動，豫。豫順以動，故天地如之，而況建侯行師乎？天地以順動，故日月不過，而四時不忒。聖人以順動，則刑罰清而民服。豫之時義，大矣哉！”">​</a></h3><h3 id="象曰-雷出地奮-豫。先王以作樂崇德-殷薦之上帝-以配祖考。" tabindex="-1">象曰：雷出地奮，豫。先王以作樂崇德，殷薦之上帝，以配祖考。 <a class="header-anchor" href="#象曰-雷出地奮-豫。先王以作樂崇德-殷薦之上帝-以配祖考。" aria-label="Permalink to “象曰：雷出地奮，豫。先王以作樂崇德，殷薦之上帝，以配祖考。”">​</a></h3><p>雷出地者，春分候也。春分之時，雷迅出地以動萬物，萬物莫不奮迅悅豫而從之也。豫，喜意也。作樂所以飾喜也。薦之上帝以配祖考，用樂之盛者。</p><h3 id="初六-鳴豫-兇-象曰-初六鳴豫-志窮兇也。" tabindex="-1">初六：鳴豫，兇 象曰：初六鳴豫，志窮兇也。 <a class="header-anchor" href="#初六-鳴豫-兇-象曰-初六鳴豫-志窮兇也。" aria-label="Permalink to “初六：鳴豫，兇 象曰：初六鳴豫，志窮兇也。”">​</a></h3><h3 id="六二-介於石-不終日-貞吉-象曰-不終日貞吉-以中正也。" tabindex="-1">六二：介於石，不終日，貞吉 象曰：不終日貞吉，以中正也。 <a class="header-anchor" href="#六二-介於石-不終日-貞吉-象曰-不終日貞吉-以中正也。" aria-label="Permalink to “六二：介於石，不終日，貞吉 象曰：不終日貞吉，以中正也。”">​</a></h3><h3 id="六三-盱豫-悔遲-有悔-象曰-盱豫有悔-位不當也。" tabindex="-1">六三：盱豫，悔遲，有悔 象曰：盱豫有悔，位不當也。 <a class="header-anchor" href="#六三-盱豫-悔遲-有悔-象曰-盱豫有悔-位不當也。" aria-label="Permalink to “六三：盱豫，悔遲，有悔 象曰：盱豫有悔，位不當也。”">​</a></h3><h3 id="九四-由豫-大有得-勿疑-朋盍簪-象曰-由豫大有得-志大行也。" tabindex="-1">九四：由豫，大有得，勿疑，朋盍簪 象曰：由豫大有得，志大行也。 <a class="header-anchor" href="#九四-由豫-大有得-勿疑-朋盍簪-象曰-由豫大有得-志大行也。" aria-label="Permalink to “九四：由豫，大有得，勿疑，朋盍簪 象曰：由豫大有得，志大行也。”">​</a></h3><h3 id="六五-貞疾-恆不死-象曰-六五貞疾-乘剛也。恆不死-中未亡也。" tabindex="-1">六五：貞疾，恆不死 象曰：六五貞疾，乘剛也。恆不死，中未亡也。 <a class="header-anchor" href="#六五-貞疾-恆不死-象曰-六五貞疾-乘剛也。恆不死-中未亡也。" aria-label="Permalink to “六五：貞疾，恆不死 象曰：六五貞疾，乘剛也。恆不死，中未亡也。”">​</a></h3><h3 id="上六-冥豫-成有渝-無咎-象曰-冥豫在上-何可長也。" tabindex="-1">上六：冥豫，成有渝，無咎 象曰：冥豫在上，何可長也。 <a class="header-anchor" href="#上六-冥豫-成有渝-無咎-象曰-冥豫在上-何可長也。" aria-label="Permalink to “上六：冥豫，成有渝，無咎 象曰：冥豫在上，何可長也。”">​</a></h3>',10)])])}const m=e(l,[["render",t]]);export{b as __pageData,m as default};
